360:void MD3Importer::ValidateHeaderOffsets() {
361:    // Check magic number
362:    if (pcHeader->IDENT != AI_MD3_MAGIC_NUMBER_BE &&
363:            pcHeader->IDENT != AI_MD3_MAGIC_NUMBER_LE)
364:        throw DeadlyImportError("Invalid MD3 file: Magic bytes not found");
365:
366:    // Check file format version
367:    if (pcHeader->VERSION > 15)
368:        ASSIMP_LOG_WARN("Unsupported MD3 file version. Continuing happily ...");
369:
370:    // Check some offset values whether they are valid
371:    if (!pcHeader->NUM_SURFACES)
372:        throw DeadlyImportError("Invalid md3 file: NUM_SURFACES is 0");
373:
374:    if (pcHeader->OFS_FRAMES >= fileSize || pcHeader->OFS_SURFACES >= fileSize ||
375:            pcHeader->OFS_EOF > fileSize) {
376:        throw DeadlyImportError("Invalid MD3 header: some offsets are outside the file");
377:    }
378:
379:    if (pcHeader->NUM_SURFACES > AI_MAX_ALLOC(MD3::Surface)) {
380:        throw DeadlyImportError("Invalid MD3 header: too many surfaces, would overflow");
381:    }
382:
383:    if (pcHeader->OFS_SURFACES + pcHeader->NUM_SURFACES * sizeof(MD3::Surface) >= fileSize) {
384:        throw DeadlyImportError("Invalid MD3 header: some surfaces are outside the file");
385:    }
386:
387:    if (pcHeader->NUM_FRAMES <= configFrameID)
388:        throw DeadlyImportError("The requested frame is not existing the file");
389:}
