109:// Load a Quake 3 shader
110:bool Q3Shader::LoadShader(ShaderData &fill, const std::string &pFile, IOSystem *io) {
111:    std::unique_ptr<IOStream> file(io->Open(pFile, "rt"));
112:    if (!file)
113:        return false; // if we can't access the file, don't worry and return
114:
115:    ASSIMP_LOG_INFO("Loading Quake3 shader file ", pFile);
116:
117:    // read file in memory
118:    const size_t s = file->FileSize();
119:    std::vector<char> _buff(s + 1);
120:    file->Read(&_buff[0], s, 1);
121:    _buff[s] = 0;
122:
123:    // remove comments from it (C++ style)
124:    CommentRemover::RemoveLineComments("//", &_buff[0]);
125:    const char *buff = &_buff[0];
126:    const char *end = buff + _buff.size();
127:    Q3Shader::ShaderDataBlock *curData = nullptr;
128:    Q3Shader::ShaderMapBlock *curMap = nullptr;
129:
130:    // read line per line
131:    for (; SkipSpacesAndLineEnd(&buff, end); SkipLine(&buff, end)) {
132:
133:        if (*buff == '{') {
134:            ++buff;
135:
136:            // append to last section, if any
137:            if (!curData) {
138:                ASSIMP_LOG_ERROR("Q3Shader: Unexpected shader section token \'{\'");
139:                return true; // still no failure, the file is there
140:            }
141:
142:            // read this data section
143:            for (; SkipSpacesAndLineEnd(&buff, end); SkipLine(&buff, end)) {
144:                if (*buff == '{') {
145:                    ++buff;
146:                    // add new map section
147:                    curData->maps.emplace_back();
148:                    curMap = &curData->maps.back();
149:
150:                    for (; SkipSpacesAndLineEnd(&buff, end); SkipLine(&buff, end)) {
151:                        // 'map' - Specifies texture file name
152:                        if (TokenMatchI(buff, "map", 3) || TokenMatchI(buff, "clampmap", 8)) {
153:                            curMap->name = GetNextToken(buff, end);
154:                        }
155:                        // 'blendfunc' - Alpha blending mode
156:                        else if (TokenMatchI(buff, "blendfunc", 9)) {
157:                            const std::string blend_src = GetNextToken(buff, end);
158:                            if (blend_src == "add") {
159:                                curMap->blend_src = Q3Shader::BLEND_GL_ONE;
160:                                curMap->blend_dest = Q3Shader::BLEND_GL_ONE;
161:                            } else if (blend_src == "filter") {
162:                                curMap->blend_src = Q3Shader::BLEND_GL_DST_COLOR;
163:                                curMap->blend_dest = Q3Shader::BLEND_GL_ZERO;
164:                            } else if (blend_src == "blend") {
165:                                curMap->blend_src = Q3Shader::BLEND_GL_SRC_ALPHA;
166:                                curMap->blend_dest = Q3Shader::BLEND_GL_ONE_MINUS_SRC_ALPHA;
167:                            } else {
168:                                curMap->blend_src = StringToBlendFunc(blend_src);
169:                                curMap->blend_dest = StringToBlendFunc(GetNextToken(buff, end));
170:                            }
171:                        }
172:                        // 'alphafunc' - Alpha testing mode
173:                        else if (TokenMatchI(buff, "alphafunc", 9)) {
174:                            const std::string at = GetNextToken(buff, end);
175:                            if (at == "GT0") {
176:                                curMap->alpha_test = Q3Shader::AT_GT0;
177:                            } else if (at == "LT128") {
178:                                curMap->alpha_test = Q3Shader::AT_LT128;
179:                            } else if (at == "GE128") {
180:                                curMap->alpha_test = Q3Shader::AT_GE128;
181:                            }
182:                        } else if (*buff == '}') {
183:                            ++buff;
184:                            // close this map section
185:                            curMap = nullptr;
186:                            break;
187:                        }
188:                    }
189:                } else if (*buff == '}') {
190:                    ++buff;
191:                    curData = nullptr;
192:                    break;
193:                }
194:
195:                // 'cull' specifies culling behaviour for the model
196:                else if (TokenMatchI(buff, "cull", 4)) {
197:                    SkipSpaces(&buff, end);
198:                    if (!ASSIMP_strincmp(buff, "back", 4)) { // render face's backside, does not function in Q3 engine (bug)
199:                        curData->cull = Q3Shader::CULL_CCW;
200:                    } else if (!ASSIMP_strincmp(buff, "front", 5)) { // is not valid keyword in Q3, but occurs in shaders
201:                        curData->cull = Q3Shader::CULL_CW;
202:                    } else if (!ASSIMP_strincmp(buff, "none", 4) || !ASSIMP_strincmp(buff, "twosided", 8) || !ASSIMP_strincmp(buff, "disable", 7)) {
203:                        curData->cull = Q3Shader::CULL_NONE;
204:                    } else {
205:                        ASSIMP_LOG_ERROR("Q3Shader: Unrecognized cull mode");
206:                    }
207:                }
208:            }
209:        } else {
210:            // add new section
211:            fill.blocks.emplace_back();
212:            curData = &fill.blocks.back();
213:
214:            // get the name of this section
215:            curData->name = GetNextToken(buff, end);
216:        }
217:    }
218:
219:    return true;
220:}
