224:bool Q3Shader::LoadSkin(SkinData &fill, const std::string &pFile, IOSystem *io) {
225:    std::unique_ptr<IOStream> file(io->Open(pFile, "rt"));
226:    if (!file)
227:        return false; // if we can't access the file, don't worry and return
228:
229:    ASSIMP_LOG_INFO("Loading Quake3 skin file ", pFile);
230:
231:    // read file in memory
232:    const size_t s = file->FileSize();
233:    std::vector<char> _buff(s + 1);
234:    const char *buff = &_buff[0];
235:    const char *end = buff + _buff.size();
236:    file->Read(&_buff[0], s, 1);
237:    _buff[s] = 0;
238:
239:    // remove commas
240:    std::replace(_buff.begin(), _buff.end(), ',', ' ');
241:
242:    // read token by token and fill output table
243:    for (; *buff;) {
244:        SkipSpacesAndLineEnd(&buff, end);
245:
246:        // get first identifier
247:        std::string ss = GetNextToken(buff, end);
248:
249:        // ignore tokens starting with tag_
250:        if (!::strncmp(&ss[0], "tag_", std::min((size_t)4, ss.length())))
251:            continue;
252:
253:        fill.textures.emplace_back();
254:        SkinData::TextureEntry &entry = fill.textures.back();
255:
256:        entry.first = ss;
257:        entry.second = GetNextToken(buff, end);
258:    }
259:
260:    return true;
261:}
