#include <cstdio>
#include <cstring>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <string>

struct aiVector3D { float x, y, z; };
using ai_real = float;

// emulate pushpack/poppack
#pragma pack(1)

struct Header {
    uint32_t IDENT;
    uint32_t VERSION;
    char NAME[64];
    int32_t FLAGS;
    uint32_t NUM_FRAMES;
    uint32_t NUM_TAGS;
    uint32_t NUM_SURFACES;
    uint32_t NUM_SKINS;
    uint32_t OFS_FRAMES;
    uint32_t OFS_TAGS;
    uint32_t OFS_SURFACES;
    uint32_t OFS_EOF;
};

struct Tag {
    char NAME[64];
    aiVector3D origin;
    ai_real orientation[3][3];
};

struct Surface {
    int32_t IDENT;
    char NAME[64];
    int32_t FLAGS;
    uint32_t NUM_FRAMES;
    uint32_t NUM_SHADER;
    uint32_t NUM_VERTICES;
    uint32_t NUM_TRIANGLES;
    uint32_t OFS_TRIANGLES;
    uint32_t OFS_SHADERS;
    uint32_t OFS_ST;
    uint32_t OFS_XYZNORMAL;
    int32_t OFS_END;
};

struct Shader { char NAME[64]; uint32_t SHADER_INDEX; };
struct Triangle { uint32_t INDEXES[3]; };
struct TexCoord { float U, V; };
struct Vertex { int16_t X, Y, Z; uint16_t NORMAL; };
#pragma pack()

static unsigned int fileSize;
static const unsigned char *mBuffer;

static void ValidateHeaderOffsets(const Header *pcHeader) {
    if (pcHeader->IDENT != 0x33504449 && pcHeader->IDENT != 0x49445033)
        { printf("throw: bad magic\n"); exit(1); }
    if (!pcHeader->NUM_SURFACES) { printf("throw: no surfaces\n"); exit(1); }
    if (pcHeader->OFS_FRAMES >= fileSize || pcHeader->OFS_SURFACES >= fileSize ||
            pcHeader->OFS_EOF > fileSize) {
        printf("throw: header offsets outside file\n"); exit(1);
    }
    if (pcHeader->OFS_SURFACES + pcHeader->NUM_SURFACES * sizeof(Surface) >= fileSize) {
        printf("throw: surfaces outside file\n"); exit(1);
    }
    if (pcHeader->NUM_FRAMES <= 0) { printf("throw: frame id\n"); exit(1); }
}

static void ValidateSurfaceHeaderOffsets(const Surface *pcSurf) {
    const int32_t ofs = int32_t((const unsigned char *)pcSurf - mBuffer);
    printf("  [validate surface at ofs=%d]\n", ofs);
    if (pcSurf->OFS_TRIANGLES + ofs + pcSurf->NUM_TRIANGLES * sizeof(Triangle) > fileSize ||
            pcSurf->OFS_SHADERS + ofs + pcSurf->NUM_SHADER * sizeof(Shader) > fileSize ||
            pcSurf->OFS_ST + ofs + pcSurf->NUM_VERTICES * sizeof(TexCoord) > fileSize ||
            pcSurf->OFS_XYZNORMAL + ofs + pcSurf->NUM_VERTICES * sizeof(Vertex) > fileSize) {
        printf("throw: surface offsets outside file\n"); exit(1);
    }
}

int main(int argc, char **argv) {
    FILE *f = fopen(argv[1], "rb");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<unsigned char> mBuffer2(sz);
    fread(&mBuffer2[0], 1, sz, f);
    mBuffer = &mBuffer2[0];
    fileSize = (unsigned int) sz;
    if (fileSize < sizeof(Header)) { printf("too small\n"); return 1; }

    const Header *pcHeader = (const Header *) mBuffer;
    ValidateHeaderOffsets(pcHeader);
    printf("header ok: NUM_SURFACES=%u NUM_TAGS=%u OFS_SURFACES=%u OFS_TAGS=%u fileSize=%u\n",
        pcHeader->NUM_SURFACES, pcHeader->NUM_TAGS, pcHeader->OFS_SURFACES, pcHeader->OFS_TAGS, fileSize);

    const Surface *pcSurfaces = (const Surface *)(mBuffer + pcHeader->OFS_SURFACES);
    const Tag *pcTags = (const Tag *)(mBuffer + pcHeader->OFS_TAGS);

    unsigned int iNum = pcHeader->NUM_SURFACES;
    while (iNum-- > 0) {
        ValidateSurfaceHeaderOffsets(pcSurfaces);

        const Vertex *pcVertices = (const Vertex *)(((const unsigned char *)pcSurfaces) + pcSurfaces->OFS_XYZNORMAL);
        const Triangle *pcTriangles = (const Triangle *)(((const unsigned char *)pcSurfaces) + pcSurfaces->OFS_TRIANGLES);
        const TexCoord *pcUVs = (const TexCoord *)(((const unsigned char *)pcSurfaces) + pcSurfaces->OFS_ST);
        const Shader *pcShaders = (const Shader *)(((const unsigned char *)pcSurfaces) + pcSurfaces->OFS_SHADERS);

        if (0 == pcSurfaces->NUM_VERTICES || 0 == pcSurfaces->NUM_TRIANGLES) {
            printf("  empty surface, OFS_END=%d, advancing\n", pcSurfaces->OFS_END);
            pcSurfaces = (const Surface *)(((const unsigned char *)pcSurfaces) + pcSurfaces->OFS_END);
            continue;
        }

        printf("  surface %s: verts=%u tris=%u\n", pcSurfaces->NAME, pcSurfaces->NUM_VERTICES, pcSurfaces->NUM_TRIANGLES);
        for (unsigned int i = 0; i < pcSurfaces->NUM_TRIANGLES; ++i) {
            for (unsigned int c = 0; c < 3; ++c) {
                uint32_t index = pcTriangles[i].INDEXES[c];
                if (index >= pcSurfaces->NUM_VERTICES) { printf("throw: bad index\n"); exit(1); }
                volatile float vx = pcVertices[index].X * (1.f/64.f);
            }
        }
        pcSurfaces = (const Surface *)(((const unsigned char *)pcSurfaces) + pcSurfaces->OFS_END);
    }

    // tags (unchecked in vulnerable version)
    if (pcHeader->NUM_TAGS) {
        for (unsigned int i = 0; i < pcHeader->NUM_TAGS; ++i, ++pcTags) {
            printf("tag %d name: %s\n", i, (const char*)pcTags->NAME);
        }
    }
    printf("done without crash\n");
    return 0;
}
